{"security_risk":"LOW","summary":"Find candidate directories containing many PDF/DOCX/PPTX files","command":"python3 - <<'PY'
import os
from collections import Counter, defaultdict
root='/root'
exts={'.pdf','.docx','.pptx'}
counts=Counter()
file_counts=defaultdict(int)
for dirpath, dirnames, filenames in os.walk(root):
    # skip huge or irrelevant dirs
    parts=dirpath.split(os.sep)
    if any(p in {'.git','node_modules','__pycache__','.venv','venv'} for p in parts):
        dirnames[:] = []
        continue
    c=0
    for fn in filenames:
        ext=os.path.splitext(fn)[1].lower()
        if ext in exts:
            c+=1
    if c:
        counts[dirpath]+=c

# show top 15 directories by count
for d,c in counts.most_common(15):
    print(f"{c:4d}  {d}")
print('\nTOTAL matching files:', sum(counts.values()))
PY"}

